mapper.select:
select ri.id, ri.seat_code, ri.price, ri.seat_type, ri.has_power, ri.has_light, ri.is_quiet, ri.store_id, ri.is_release, la.seat_id is not null is_check_in, la.end_date booking_end_date, ai.id store_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release store_is_release from seat ri left join booking_order la on ri.id = la.seat_id and la.is_deleted = 0 and la.status in (2,5) left join study_store ai on ri.store_id = ai.id and ai.is_deleted = 0
ri.is_deleted = 0
ai.province_id = #{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and ri.store_id = #{queryVo.storeId}
